const raw = $input.first().json.output || "";
let parsed = null;

try {
  const match = raw.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
  const jsonString = match ? match[1] : raw;
  parsed = JSON.parse(jsonString);
} catch (e) {
  // If not JSON, use the raw output as summary!
  parsed = {
    status: "success",
    intent: "general_query",
    extracted_entities: {},
    summary: raw,
    raw_response: raw
  };
}

if (!parsed.raw_response) {
  parsed.raw_response = raw;
}
if (!parsed.summary && raw) {
  parsed.summary = raw;
}

return [parsed];
